# Requirements - public order lookup API

We are exposing the order lookup endpoint to our mobile app.

## Requirements

1. No public access to the API itself. Everything reaches it through
   CloudFront.
2. CloudFront must have a WAF attached with a rate limit.
3. Requests must be authenticated (IAM auth is fine for now).
4. Access logs retained for a year, encrypted with a customer-managed key.
5. Serve only to our launch markets: PL, NO, SE, DK, DE.

## Out of scope

Custom domain and ACM certificate - we ship on the default CloudFront
certificate for this milestone.

=== THE PLAN (case1-cloudfront/main.tf), verbatim except where marked ===

resource "aws_api_gateway_rest_api" "this" {
  name        = "${var.name}-api"
  description = "Internal API. The requirements say it must only be reachable through CloudFront."
  lifecycle { create_before_destroy = true }
}

resource "aws_api_gateway_client_certificate" "this" {
  description = "Lets the origin verify calls came from API Gateway."
}

resource "aws_api_gateway_request_validator" "this" {
  name                        = "${var.name}-validator"
  rest_api_id                 = aws_api_gateway_rest_api.this.id
  validate_request_body       = true
  validate_request_parameters = true
}

resource "aws_api_gateway_method_settings" "prod" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  stage_name  = aws_api_gateway_stage.prod.stage_name
  method_path = "*/*"
  settings {
    logging_level        = "ERROR"
    metrics_enabled      = true
    caching_enabled      = true
    cache_data_encrypted = true
  }
}

resource "aws_api_gateway_resource" "orders" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = "orders"
}

resource "aws_api_gateway_method" "get_orders" {
  rest_api_id          = aws_api_gateway_rest_api.this.id
  resource_id          = aws_api_gateway_resource.orders.id
  http_method          = "GET"
  authorization        = "AWS_IAM"
  request_validator_id = aws_api_gateway_request_validator.this.id
}

resource "aws_api_gateway_integration" "get_orders" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.orders.id
  http_method = aws_api_gateway_method.get_orders.http_method
  type        = "MOCK"
  request_templates = { "application/json" = "{\"statusCode\": 200}" }
}

resource "aws_api_gateway_deployment" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  depends_on  = [aws_api_gateway_integration.get_orders]
  lifecycle { create_before_destroy = true }
}

resource "aws_api_gateway_stage" "prod" {
  deployment_id         = aws_api_gateway_deployment.this.id
  rest_api_id           = aws_api_gateway_rest_api.this.id
  stage_name            = "prod"
  xray_tracing_enabled  = true
  cache_cluster_enabled = true
  cache_cluster_size    = "0.5"
  client_certificate_id = aws_api_gateway_client_certificate.this.id
  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api.arn
    format          = "{\"requestId\":\"$context.requestId\",\"ip\":\"$context.identity.sourceIp\"}"
  }
}

resource "aws_cloudwatch_log_group" "api" {
  name              = "/aws/apigateway/${var.name}"
  retention_in_days = 365
  kms_key_id        = aws_kms_key.logs.arn
}

resource "aws_kms_key" "logs" {
  description             = "CMK for ${var.name} API access logs"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

# --- the edge the requirements asked for ---

resource "aws_wafv2_web_acl" "edge" {
  provider = aws.us_east_1
  name     = "${var.name}-edge"
  scope    = "CLOUDFRONT"
  default_action { allow {} }
  rule {
    name     = "log4j"
    priority = 0
    override_action { none {} }
    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
        vendor_name = "AWS"
      }
    }
    visibility_config { cloudwatch_metrics_enabled = true, metric_name = "${var.name}-edge-log4j", sampled_requests_enabled = true }
  }
  rule {
    name     = "rate-limit"
    priority = 1
    action { block {} }
    statement { rate_based_statement { limit = 2000, aggregate_key_type = "IP" } }
    visibility_config { cloudwatch_metrics_enabled = true, metric_name = "${var.name}-rate-limit", sampled_requests_enabled = true }
  }
  visibility_config { cloudwatch_metrics_enabled = true, metric_name = "${var.name}-edge", sampled_requests_enabled = true }
}

resource "aws_cloudfront_distribution" "this" {
  enabled         = true
  comment         = "${var.name} edge"
  web_acl_id      = aws_wafv2_web_acl.edge.arn
  price_class     = "PriceClass_100"
  is_ipv6_enabled = true

  origin {
    domain_name = "${aws_api_gateway_rest_api.this.id}.execute-api.${var.region}.amazonaws.com"
    origin_id   = "apigw"
    origin_path = "/${aws_api_gateway_stage.prod.stage_name}"
    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    target_origin_id           = "apigw"
    response_headers_policy_id = data.aws_cloudfront_response_headers_policy.security.id
    viewer_protocol_policy     = "redirect-to-https"
    allowed_methods            = ["GET", "HEAD"]
    cached_methods             = ["GET", "HEAD"]
    forwarded_values {
      query_string = true
      headers      = ["Authorization"]
      cookies { forward = "none" }
    }
    # Authorization is per-caller (SigV4), so caching is disabled outright.
    min_ttl     = 0
    default_ttl = 0
    max_ttl     = 0
  }

  logging_config {
    bucket          = aws_s3_bucket.logs.bucket_domain_name
    prefix          = "cloudfront/"
    include_cookies = false
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["PL", "NO", "SE", "DK", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
    minimum_protocol_version       = "TLSv1.2_2021"
  }
}

# --- log sink for the edge ---
# aws_s3_bucket.logs (bucket_prefix "${var.name}-logs-"), plus:
#   ownership_controls  = BucketOwnerEnforced
#   sse configuration   = aws:kms with kms_master_key_id = aws_kms_key.logs.arn
#   versioning          = Enabled
#   bucket logging      = self, prefix "access/"
#   public_access_block = all four flags true
#   lifecycle           = expire after 365 days, abort incomplete MPU after 7

# --- the scanner's own recommendation, applied ---
# Checkov CKV2_AWS_29 wants a WAF in front of the API Gateway stage. Here it is.

resource "aws_wafv2_web_acl" "api" {
  name  = "${var.name}-api"
  scope = "REGIONAL"
  default_action { allow {} }
  rule {
    name     = "log4j"
    priority = 1
    override_action { none {} }
    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
        vendor_name = "AWS"
      }
    }
    visibility_config { cloudwatch_metrics_enabled = true, metric_name = "${var.name}-api-log4j", sampled_requests_enabled = true }
  }
  visibility_config { cloudwatch_metrics_enabled = true, metric_name = "${var.name}-api", sampled_requests_enabled = true }
}

resource "aws_wafv2_web_acl_association" "api" {
  resource_arn = aws_api_gateway_stage.prod.arn
  web_acl_arn  = aws_wafv2_web_acl.api.arn
}

resource "aws_wafv2_web_acl_logging_configuration" "api" {
  resource_arn            = aws_wafv2_web_acl.api.arn
  log_destination_configs = [aws_cloudwatch_log_group.waf_api.arn]
}

resource "aws_cloudwatch_log_group" "waf_api" {
  name              = "aws-waf-logs-${var.name}-api"
  retention_in_days = 365
  kms_key_id        = aws_kms_key.logs.arn
}

data "aws_cloudfront_response_headers_policy" "security" { name = "Managed-SecurityHeadersPolicy" }
data "aws_caller_identity" "current" {}

resource "aws_kms_key_policy" "logs" {
  key_id = aws_kms_key.logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "AllowAccountAdmin"
      Effect    = "Allow"
      Principal = { AWS = "[redacted: account root ARN]" }
      Action    = "kms:*"
      Resource  = "*"
    }]
  })
}

# WAF edge logging: aws_wafv2_web_acl_logging_configuration.edge (us-east-1) ->
# aws_cloudwatch_log_group.waf_edge (us-east-1, 365 days, encrypted with a
# second CMK aws_kms_key.logs_us_east_1, also in us-east-1, with the same
# account-root key policy). CLOUDFRONT-scope WAF logging requires the log group
# in us-east-1, and CloudWatch Logs requires the key in the same region as the
# group, hence the second key.

